-- Two schemas, a cross-schema FK, an enum and a view, plus the things introspection treats
-- specially: both identity kinds, a serial column, a composite key, a self-referencing FK,
-- a check, a partial (read-only) index and comments.
CREATE SCHEMA billing;

CREATE TYPE public.user_status AS ENUM ('active', 'banned');

CREATE TABLE public.users (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email text NOT NULL UNIQUE,
  status public.user_status NOT NULL DEFAULT 'active',
  invited_by bigint REFERENCES public.users (id),
  created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.users IS 'Registered users';
COMMENT ON COLUMN public.users.email IS 'Login email';

CREATE TABLE billing.invoices (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  issued date NOT NULL,
  user_id bigint NOT NULL REFERENCES public.users (id) ON DELETE CASCADE,
  total numeric(10, 2) NOT NULL DEFAULT 0 CHECK (total >= 0),
  PRIMARY KEY (id, issued)
);
CREATE INDEX invoices_user_id_idx ON billing.invoices (user_id);
CREATE INDEX invoices_open_idx ON billing.invoices (total) WHERE total > 0;

CREATE TABLE billing.line_items (
  id serial PRIMARY KEY,
  invoice_id integer NOT NULL,
  issued date NOT NULL,
  label varchar(80),
  FOREIGN KEY (invoice_id, issued) REFERENCES billing.invoices (id, issued)
);

CREATE VIEW billing.open_invoices AS
  SELECT id, issued, total FROM billing.invoices WHERE total > 0;
